int load_tss_state(struct x86_emulate_ctxt *ctxt, struct tss_segment_16 *tss)
{
    /* Initialize emulator context with values from the TSS */
    ctxt->regs->eip = tss->eip;
    ctxt->regs->eflags = tss->eflags;

    /* Load general-purpose registers */
    ctxt->regs->eax = tss->eax;
    ctxt->regs->ecx = tss->ecx;
    ctxt->regs->edx = tss->edx;
    ctxt->regs->ebx = tss->ebx;
    ctxt->regs->esp = tss->esp;
    ctxt->regs->ebp = tss->ebp;
    ctxt->regs->esi = tss->esi;
    ctxt->regs->edi = tss->edi;

    /* Set segment selectors */
    ctxt->regs->cs = tss->cs;
    ctxt->regs->ss = tss->ss;
    ctxt->regs->ds = tss->ds;
    ctxt->regs->es = tss->es;
    ctxt->regs->fs = tss->fs;
    ctxt->regs->gs = tss->gs;

    /* Attempt to load segment descriptors */
    int result = load_segment_descriptor(ctxt, tss->cs, &ctxt->regs->cs);
    if (result != X86EMUL_CONTINUE)
        return result;

    result = load_segment_descriptor(ctxt, tss->ss, &ctxt->regs->ss);
    if (result != X86EMUL_CONTINUE)
        return result;

    result = load_segment_descriptor(ctxt, tss->ds, &ctxt->regs->ds);
    if (result != X86EMUL_CONTINUE)
        return result;

    result = load_segment_descriptor(ctxt, tss->es, &ctxt->regs->es);
    if (result != X86EMUL_CONTINUE)
        return result;

    result = load_segment_descriptor(ctxt, tss->fs, &ctxt->regs->fs);
    if (result != X86EMUL_CONTINUE)
        return result;

    result = load_segment_descriptor(ctxt, tss->gs, &ctxt->regs->gs);
    if (result != X86EMUL_CONTINUE)
        return result;

    return X86EMUL_CONTINUE;
}
